public class HackathonRegistration {String name,team;boolean registered;HackathonRegistration(String n,String t){name=n;team=t;registered=true;}HackathonRegistration(String n){this(n,"Unassigned");}void print(){System.out.println(name+" | "+team+" | Registered: "+registered);}public static void main(String[]x){String[]n={"Ravi","Meera","Karthik","Divya"},t={"ByteBusters","","CodeCrafters",""};for(int i=0;i<n.length;i++){HackathonRegistration p=t[i].equals("")?new HackathonRegistration(n[i]):new HackathonRegistration(n[i],t[i]);p.print();}}}
